window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d2c918280d10769c"]={"versions": [{"id": "FIG-d2c918280d10769c", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Tracing-Diagramm zur Darstellung der zulässigen Modellierungsbeziehungen und Datentyptraces zwischen der AUTOSAR Abstract Platform (XP) und konkreten Plattformen (Classic Platform, CP; Adaptive Platform, AP). Der Kontext umfasst die vertikale Zuordnung von Datentypen auf Applikationsebene zu konkreten Plattformimplementierungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in drei Blöcke:</p>\n<ul class=\"fig-list\"><li>Oberer Block: Plattformebene <code>Abstract Platform</code> mit der Entität <code>(XP) ApplicationDataType</code>.\n</li><li>Mittlerer Block: Plattformebene <code>Classic/Adaptive Platform</code> mit der Entität <code>(CP/AP) ApplicationDataType</code>.\n</li><li>Unterer Block: Plattformebene <code>Classic/Adaptive Platform</code> mit der Entität <code>AbstractImplementationDataType</code>.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Beziehungen:</p>\n<ul class=\"fig-list\"><li>Zwischen <code>(XP) ApplicationDataType</code> und <code>(CP/AP) ApplicationDataType</code> besteht eine bidirektionale gestrichelte Pfeilverbindung mit dem Stereotyp <code>&lt;&lt;tracing&gt;&gt;</code>.\n</li><li>Zwischen <code>(CP/AP) ApplicationDataType</code> und <code>AbstractImplementationDataType</code> besteht eine bidirektionale durchgezogene Pfeilverbindung mit der Bezeichnung <code>DataTypeMap</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Modellierungs- und Tracing-Beziehung: Es existiert kein dynamischer Sequenzablauf zur Laufzeit. Modellierungsseitig erfolgt das Tracing zwischen XP- und CP/AP-Ebene direkt über die korrespondierenden Applikationsdatentypen. Innerhalb der konkreten Plattform wird der <code>(CP/AP) ApplicationDataType</code> über ein <code>DataTypeMap</code> auf den plattformspezifischen <code>AbstractImplementationDataType</code> abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Tracing von Datentypen zwischen XP und CP/AP ist normativ ausschließlich auf der Abstraktionsebene der <code>ApplicationDataType</code>-Elemente zulässig (<code>&lt;&lt;tracing&gt;&gt;</code>). Ein direktes Tracing von XP-Applikationsdatentypen auf konkrete Implementierungsdatentypen (<code>AbstractImplementationDataType</code>) ist nicht zulässig; die Transformation auf Implementierungsebene erfolgt erst innerhalb der jeweiligen Zielplattform über das <code>DataTypeMap</code>-Konzept.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-00150f9432a1f5be", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Struktur- und Tracing-Diagramm zur Darstellung der zulässigen Modellierungsbeziehungen und Datentyptraces zwischen der AUTOSAR Abstract Platform (XP) und konkreten Plattformen (Classic Platform, CP; Adaptive Platform, AP). Der Kontext umfasst die vertikale Zuordnung von Datentypen auf Applikationsebene zu konkreten Plattformimplementierungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in drei Blöcke:</p>\n<ul class=\"fig-list\"><li>Oberer Block: Plattformebene <code>Abstract Platform</code> mit der Entität <code>ApplicationDataType</code>.\n</li><li>Mittlerer Block: Plattformebene <code>Classic/Adaptive Platform</code> mit der Entität <code>ApplicationDataType</code>.\n</li><li>Unterer Block: Plattformebene <code>Classic/Adaptive Platform</code> mit der Entität <code>AbstractImplementationDataType</code>.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Beziehungen:</p>\n<ul class=\"fig-list\"><li>Zwischen dem oberen <code>ApplicationDataType</code> und dem mittleren <code>ApplicationDataType</code> besteht eine bidirektionale gestrichelte Pfeilverbindung mit dem Stereotyp <code>&lt;&lt;tracing&gt;&gt;</code>.\n</li><li>Zwischen dem mittleren <code>ApplicationDataType</code> und dem unteren <code>AbstractImplementationDataType</code> besteht eine bidirektionale durchgezogene Pfeilverbindung mit der Bezeichnung <code>DataTypeMap</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Modellierungs- und Tracing-Beziehung: Es existiert kein dynamischer Sequenzablauf zur Laufzeit. Modellierungsseitig erfolgt das Tracing zwischen XP- und CP/AP-Ebene direkt über die korrespondierenden Applikationsdatentypen. Innerhalb der konkreten Plattform wird der <code>(CP/AP) ApplicationDataType</code> über ein <code>DataTypeMap</code> auf den plattformspezifischen <code>AbstractImplementationDataType</code> abgebildet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Tracing von Datentypen zwischen XP und CP/AP ist normativ ausschließlich auf der Abstraktionsebene der <code>ApplicationDataType</code>-Elemente zulässig (<code>&lt;&lt;tracing&gt;&gt;</code>). Ein direktes Tracing von XP-Applikationsdatentypen auf konkrete Implementierungsdatentypen (<code>AbstractImplementationDataType</code>) ist nicht zulässig; die Transformation auf Implementierungsebene erfolgt erst innerhalb der jeweiligen Zielplattform über das <code>DataTypeMap</code>-Konzept.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-d2c918280d10769c", "to": "FIG-00150f9432a1f5be", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Im oberen Block (Abstract Platform) wurde der Präfix <code>(XP) </code> vor <code>ApplicationDataType</code> entfernt.\n</li><li>Im mittleren Block (Classic/Adaptive Platform) wurde der Präfix <code>(CP/AP) </code> vor <code>ApplicationDataType</code> entfernt.\n</li></ul>"}]};
